mapper.select:
SELECT FROM ad_account_asset WHERE deleted_at = 0 AND account_id IN
#{accountId}
ORDER BY created_at DESC, id DESC

sql.if:
AND EXISTS ( SELECT 1 FROM ad_account_asset_assignment usage_assignment WHERE usage_assignment.ad_account_asset_id = ad_account_asset.id AND usage_assignment.assignment_status = 'ACTIVE' AND usage_assignment.deleted_at = 0 AND (
usage_assignment.user_name LIKE CONCAT('%', #{usageUser}, '%')
) )

AND EXISTS ( SELECT 1 FROM ad_account_asset_assignment inventory_assignment WHERE inventory_assignment.ad_account_asset_id = ad_account_asset.id AND inventory_assignment.assignment_status = 'ACTIVE' AND inventory_assignment.deleted_at = 0 AND (
inventory_assignment.user_name LIKE CONCAT('%', #{inventoryAssigneeName}, '%')
) )

AND EXISTS ( SELECT 1 FROM ad_account_asset_assignment department_assignment JOIN sys_user usage_user ON usage_user.id = department_assignment.user_id AND usage_user.deleted_at = 0 LEFT JOIN sys_department department ON department.id = usage_user.primary_department_id AND department.deleted_at = 0 WHERE department_assignment.ad_account_asset_id = ad_account_asset.id AND department_assignment.assignment_status = 'ACTIVE' AND department_assignment.deleted_at = 0 AND (
department.dept_name LIKE CONCAT('%', #{usageDepartment}, '%')
) )

mapper.select:
SELECT FROM ad_account_asset WHERE deleted_at = 0 AND id IN
#{id}
ORDER BY created_at DESC, id DESC

SELECT COUNT(*)
FROM ad_account_asset_change_event
WHERE ad_account_asset_id = #{adAccountAssetId}
  AND event_type = #{eventType}

mapper.insert:
INSERT INTO ad_account_asset_import_log (
    file_name, total_count, success_count, failure_count,
    failure_details, failed_file_ciphertext, operator_id
) VALUES (
    #{fileName}, #{totalCount}, #{successCount}, #{failureCount},
    CAST(#{failureDetails} AS JSON), #{failedFileCiphertext}, #{operatorId}
)

mapper.select:
SELECT id, file_name, total_count, success_count, failure_count,
       failure_details, failed_file_ciphertext, operator_id, created_at
FROM ad_account_asset_import_log
WHERE id = #{id}
  AND operator_id = #{operatorId}
